DOC.got("gh/rs/isHoldAmiiboMode.cpp","// Nom démêlé : rs::isHoldAmiiboMode\n// Symbole manglé : isHoldAmiiboMode\n// undefined8 rs::isHoldAmiiboMode(IUseSceneObjHolder *param_1); @ .text::00677078\n\n\n/* rs::isHoldAmiiboMode(al::IUseSceneObjHolder const*) */\n\nundefined8 rs::isHoldAmiiboMode(IUseSceneObjHolder *param_1)\n\n{\n  int iVar1;\n  long lVar2;\n  undefined8 uVar3;\n  \n  lVar2 = al::getSceneObj(param_1,0x12);\n  if (*(char *)(lVar2 + 0x245) != '\\0') {\n    return 0;\n  }\n  lVar2 = al::getSceneObj(param_1,0x12);\n  if (*(char *)(lVar2 + 0x245) == '\\0') {\n    iVar1 = al::getMainControllerPort();\n  }\n  else {\n    iVar1 = al::getPlayerControllerPort(0);\n  }\n  uVar3 = al::isPadHoldRight(iVar1);\n  return uVar3;\n}\n\n");